{{LSL Constant
|name=JSON_ARRAY
|type=string
|value="﷒"
|dvalue={{HoverText|"﷒"|Special Unicode Character&#x000d;Unicode:&#x0009;U+FDD2&#x000d;HTML:&#x0009;&amp;#xFDD2;&#x000d;llUnescapeUrl({{String|%EF%B7%92}});}}
|desc=Used with the [[llList2Json]] function to indicate that the provided list (which may be empty) is to be used to encode and return a string serialization of a Json array.

Also a possible return value for the [[llJsonValueType]] function that indicates the Json data type of at the specifier location within a given Json text is, in fact, a Json array.
|constants={{LSL Constants/JSON}}
|examples=Showing usage to form a Json array:
<source lang="lsl2">string jsonText;

default
{
	state_entry()
	{
		jsonText = llList2Json(JSON_ARRAY, ["A", 3, "B", <1.0,1.0,1.0>, "C", "A phrase", "D", PI]);
	}
	touch_start(integer total_number)
	{
		// In the resulting Json array, all Values are separated by a comma (,).
		llOwnerSay(jsonText); //  ["A",3,"B","<1.000000, 1.000000, 1.000000>","C","A phrase","D",3.141593]
	}
}</source>

Showing usage to determine if a Value within a Json text is an array:
<source lang="lsl2">string jsonText;

default
{
	state_entry()
	{
		// Set jsonText to [3,{"A":77,"B":66},"A phrase"]
		// A Json array whose second element is a Json object
		jsonText = "[3,{\"A\":77,\"B\":66},\"A phrase\"]";
		llOwnerSay(jsonText);
	}
	touch_start(integer total_number)
	{
		// Test the entirety of the Json text to see if it's an array
		// Note use of the empty list for this
		if (llJsonValueType(jsonText, []) == JSON_ARRAY)
		{
			llOwnerSay("The supplied string is a Json array."); // TRUE
		} else {
			llOwnerSay("The supplied string is not a Json array.");
		}

		// Test second element of the array
		if (llJsonValueType(jsonText, [1]) == JSON_ARRAY)
		{
			llOwnerSay("The second element of the array is a Json array.");
		} else {
			llOwnerSay("The second element of the array is not a Json array."); // TRUE
		}
	}
}</source>
|functions=
{{LSL DefineRow||[[llList2Json]]|}}
{{LSL DefineRow||[[llJsonValueType]]|}}
|events
|cat1=JSON
|cat2
|cat3
|cat4
|self
}}

{{LSL Constant
|name=JSON_DELETE
|type=string
|value="�"
|dvalue={{HoverText|"�"|Special Unicode Character&#x000d;Unicode:&#x0009;U+FDD8&#x000d;HTML:&#x0009;&amp;#xFDD8;&#x000d;llUnescapeUrl({{String|%EF%B7%98}});}}
|desc=A [[:Category:LSL_Constants|constant]] used to delete a value within a [http://www.json.org/ JSON] text string.
|constants={{LSL Constants/JSON}}
|examples=<source lang="lsl2">default
{
    touch_start(integer num_detected)
    {
        string jsonString = "[1,2,3,4,5]";

        llSay(PUBLIC_CHANNEL, "Original: " + jsonString);

    //  we remove the first item (list has zero-based index!)
        jsonString = llJsonSetValue(jsonString, [0], JSON_DELETE);

    //  "[2,3,4,5]"
        llSay(PUBLIC_CHANNEL, "Modified: " + jsonString);
    }
}</source>
|caveats=*Using JSON_DELETE will '''not''' prune empty objects or arrays at higher levels.
* Using JSON_DELETE to delete a non-existent array or object element in a JSON string will return [[JSON_INVALID]], not an unaltered string.
|functions=
{{LSL DefineRow||[[llJsonSetValue]]|}}
|events
|cat1=JSON
|cat2
|cat3
|cat4
|self
}}

{{LSL Constant
|name=JSON_FALSE
|type=string
|value="�"
|dvalue={{HoverText|"�"|Special Unicode Character&#x000d;Unicode:&#x0009;U+FDD7&#x000d;HTML:&#x0009;&amp;#xFDD7;&#x000d;llUnescapeUrl({{String|%EF%B7%97}});}}
|desc=Return value for [[llJsonValueType]] function indicating the data type of a given address specifier in a given string-serialized JSON object.

Also used to set the bare word 'false' as a Value within a Json text using [[llJsonSetValue]] and [[llList2Json]]. 
|constants={{LSL Constants/JSON}}
|examples=
<source lang="lsl2">
//  showing difference between JSON_TRUE & JSON_FALSE
//  and their LSL equivalents within a JSON text string

run_json_test(string input)
{
//  [true,false]
    say(input);

//  unicode equivalent of JSON_FALSE
    say(llJsonGetValue(input, [1]));

    input = llList2Json(JSON_ARRAY, [TRUE, FALSE]);

//  [1,0]
    say(input);

//  0
    say(llJsonGetValue(input, [1]));
}

say(string message)
{
    llOwnerSay(message);
//  llRegionSayTo(llGetOwner(), PUBLIC_CHANNEL, message);
//  llWhisper(PUBLIC_CHANNEL, message);
}

default
{
    touch_end(integer num_detected)
    {
        string TEST_STRING_JSON = llList2Json(JSON_ARRAY, [
                                              JSON_TRUE, JSON_FALSE]);

//      copy 'TEST_STRING_JSON' from the following function call
//      to the string 'input' in the function declaration
//      and run a test on 'input' to not (!) modify 'TEST_STRING_JSON'
//      but its copy instead

        run_json_test(TEST_STRING_JSON);
    }
}
</source>
