|cat1=Pathfinding
}}

[[Category:Experience Tools]]
{{LSL_Function
|inject-2={{LSL Function/KeyValue|k|v|dataserver|value=value|d2_type=string|d2_name=value}}{{LSL Function/Experience|true}}
|func=llCreateKeyValue
|func_desc=Start an asynchronous transaction to create a key-value pair associated with the script's {{LSLGC|Experience}} using the given key ({{LSLPT|k}}) and value ({{LSLPT|v}}).
|func_footnote=If the key already exists the [[dataserver]] will return a failure along with the error [[XP_ERROR_STORAGE_EXCEPTION]].<br/>
<br/>
As of Jan 1, 2016 maximum bytes is 1011 for key and 4095 for value for both LSO and Mono scripts.
|return_type=key|return_subtype=handle
|return_text=that can be used to identify the corresponding [[dataserver]] event to determine if this command succeeded or failed.
|p1_type=string|p1_name=k
|p2_type=string|p2_name=v
|also_functions=
*[[llGetExperienceErrorMessage]]
*[[llReadKeyValue]]
*[[llUpdateKeyValue]]
*[[llDeleteKeyValue]]
*[[llDataSizeKeyValue]]
*[[llKeyCountKeyValue]]
*[[llKeysKeyValue]]
|examples=<syntaxhighlight lang="lsl2">key trans;
default
{
    touch_start(integer total_number)
    {
        trans = llCreateKeyValue("FOO", "BAR");
    }



    dataserver(key t, string value)
    {
        if (t == trans)
        {
            // our llCreateKeyValue transaction is done
            integer result = (integer)llGetSubString(value, 0, 0);
            if (result == 1)
            {
                // the key-value pair was successfully created
                llSay(0, "New key-value pair was created");
            }
            else
            {
                // the key-value pair was not created
                integer error = (integer)(llGetSubString(value, 2, -1));
                llSay(0, "Key-value failed to create: " + llGetExperienceErrorMessage(error));
            }
        }
    } 
}</syntaxhighlight>
|cat1=Experience
|cat2=Experience/Data
|cat3=Dataserver
|caveats=* It is recommended that keys do not contain commas due to [[llKeysKeyValue]] returning keys in CSV format.
|* If this function returns an [[XP_ERROR_STORAGE_EXCEPTION]], subsequent attempts to create the same KVP key may also fail, even if it appears that no key has been created. For that reason, it may be preferable to use [[llUpdateKeyValue]], which will overwrite any existing value or will create a new KVP key if none exists with that name.
|haiku={{Haiku|Clear sky with bright sun|Wonderful key created|from an old value}}
}}

{{LSL_Function
|inject-2={{LSL_Function/permission|PERMISSION_CHANGE_LINKS|grant=the owner}}{{LSL_Function/prim|target|sim=*}}
|func_id=141|func_sleep=0.1|func_energy=10.0
|func=llCreateLink|sort=CreateLink
|p1_type=key|p1_name=target
|p2_type=integer|p2_name=parent
|p2_desc=If [[FALSE]], then {{LSLP|target}} becomes the root. If [[TRUE]], then the script's object becomes the root.
|p2_hover=If FALSE, then 'target' becomes the root. If TRUE, then the script's object becomes the root.
|func_footnote={{LSLP|target}} must be modifiable and have the same owner.<br/>
This object must also be modifiable.
|func_desc=Attempt to link the script's object with {{LSLP|target}}.
|spec=The prims for the child object ({{LSLP|target}} if {{LSLP|parent}} is [[TRUE]], script's object if {{LSLP|parent}} is [[FALSE]]) are inserted into the parent object's link set starting at link number 2. For example, if the link order for the parent object is A1, A2, A3 and the link order of the child object is B1, B2, B3, then the link order of the resulting object will be A1, B1, B2, B3, A2, A3.
|caveats=*If {{LSLP|target}} is not in the region, not a prim, or is attached to an avatar, an error is shouted on [[DEBUG_CHANNEL]].
*If either the object or the {{LSLP|target}} are not modifiable or of different owners, then an error is shouted on [[DEBUG_CHANNEL]].
*If the the parent object and {{LSLP|target}} are too far apart they will fail to link.
**The maximum distance is further explained here: [[Linkability Rules]]
*This function silently fails if called from a script inside an attachment.
|constants
|examples=<source lang="lsl2">// Rez an object and link it as a child prim.
string ObjectName = "Object Name Here";
// NOTE: must be a name of an object in this object's inventory.

default
{
    touch_start(integer count)
    {
        // When the object is touched, make sure we can do this before trying.
        llRequestPermissions(llGetOwner(), PERMISSION_CHANGE_LINKS);
    }
    run_time_permissions(integer perm)
    {
        // Only bother rezzing the object if will be able to link it.
        if (perm & PERMISSION_CHANGE_LINKS)
            llRezObject(ObjectName, llGetPos() + <0,0,0.5>, ZERO_VECTOR, llGetRot(), 0);
        else
            llOwnerSay("Sorry, we can't link.");
    }
    object_rez(key id)
    {
        // NOTE: under some conditions, this could fail to work.
        // This is the parent object.  Create a link to the newly-created child.
        llCreateLink(id, TRUE);
    }
}</source>

|helpers=
<source lang="lsl2">
// child prim key
key kChild = NULL_KEY;
integer bLink = TRUE;       // we suppose this script is on a linked object
default
{

    state_entry()
    {
        // get the permission to change the link
        llRequestPermissions(llGetOwner(), PERMISSION_CHANGE_LINKS);

        // get the child key
        kChild = llGetLinkKey(2);
    }


    touch_start(integer nTotalCliquor)
    {
        if (bLink)
        {
            // break all my links, wait 1.5 sec
            llBreakAllLinks();
            llSleep(1.5);

            // i'm unlinked
            llSay(0, "Unlinked, click to link");
            bLink = FALSE;
        }
        else
        {
            // redo my link
            llCreateLink(kChild, TRUE);   
            llSleep(1.5);

            // i'm linked
            llSay(0, "Linked, click to unlink");
            bLink = TRUE;
        }
    }
}               
</source>
|also_functions={{LSL DefineRow||[[llBreakLink]]|Break a link}}
{{LSL DefineRow||[[llBreakAllLinks]]|Break all links}}
|also_tests
|also_events={{LSL DefineRow||[[changed]]|[[CHANGED_LINK]]}}
|also_articles=
{{LSL DefineRow||[[Linkability Rules]]|}}
|notes
|cat1=Link
|cat2=Link/Management
|cat3
|cat4
}}

{{LSL Function
|func_id=196|func_sleep=0.0|func_energy=10.0
|func=llCSV2List|return_type=list|p1_type=string|p1_name=src
|func_footnote=
To convert a list into a comma-separated string use [[llList2CSV]].<br/>
Do not confuse this function with the {{Wikipedia|Comma-separated values|CSV}} format, it is ''not'' the CSV format.
|func_desc=This function takes a string of values separated by commas, and turns it into a list.
|return_text=made by parsing '''src''', a string of comma separated values.
|spec=
=== Vectors & Rotations ===
Anything between "<" and ">" is considered a single value regardless of the existence of a comma between. 

This ensures that [[vector]]s and [[rotation]]s get treated as a single value, with no additional cleanup needed afterward.

Note, though, that for every "<" there needs to be a corresponding ">" or it will consume the rest of the string. For example,
{{{!}}
{{LSL DefineRow||&#32;<code>llCSV2List("<>,>,a")</code>|returns <code>["<>", ">", "a"]</code>|(Second ">" is isolated)}}
{{LSL DefineRow||&#32;<code>llCSV2List("<<>,>,a")</code>|returns <code>["<<>,>", "a"]</code>|(Regularly paired)}}
{{LSL DefineRow||&#32;<code>llCSV2List("<<<>,>,a")</code>|returns <code>["<<<>,>,a"]</code>|(Third "<" lost its opposite one)}}
{{!}}}

=== Types ===

The function makes no assumptions about what the list entry types should be, all elements in the resulting list will be strings. It is important to know that the llList2* functions implicit typecasts do not work the same as explicit typecast. The following table gives code examples for each type that will yield the best results.

{{{!}} {{Prettytable|style=margin-top:0;}}
{{!}}- {{Hl2}}
! Target
! Code
! Description
{{!}}-
{{!}}[[integer]]
{{!}}<code>(integer)[[llList2String]](mlist, mint)</code>
{{!}}[[llList2Integer]] does not support the hex format
{{!}}-
{{!}}[[float]]
{{!}}<code>(float)[[llList2String]](mlist, mint)</code>
{{!}}[[llList2Float]] does not support the scientific or hexadecimal notations
{{!}}-
{{!}}[[string]]
{{!}}<code>[[llList2String]](mlist, mint)</code>
{{!}}Always Safe
{{!}}-
{{!}}[[key]]
{{!}}<code>[[llList2Key]](mlist, mint)</code>
{{!}}Always Safe
{{!}}-
{{!}}[[vector]]
{{!}}<code>(vector)[[llList2String]](mlist, mint)</code>
{{!}}[[llList2Vector]] will return a zero vector
{{!}}-
{{!}}[[rotation]]
{{!}}<code>(rotation)[[llList2String]](mlist, mint)</code>
{{!}}[[llList2Rot]] will return a zero rotation
{{!}}}

=== Whitespace ===

[[llCSV2List]] consumes the first leading space from all values :

<syntaxhighlight lang="lsl2">
list tmp = llCSV2List("first , second , third");
//returns ["first ","second ","third"]
//not ["first "," second "," third"]
</syntaxhighlight>
|caveats=
* If a "<" does not have a matching ">", the remainder of the string will be a single value, even if the "<" is in the middle of the value, see [[#Vectors & Rotations|Vectors & Rotations]] for further details.
* All items in the returned list are strings.
* If an empty string is parsed, the result will a list containing an empty string: [""] (not an empty list).
* When used with lists that are generated based off assets in inventory, [[llCSV2List]] should not be used, as inventory assets can contain commas as part of their names.
|constants
|examples=
<syntaxhighlight lang="lsl2">
default
{
    state_entry()
    {
        string csv = "first,second,third";
        list my_list = llCSV2List(csv);
        llOwnerSay("CSV: " + csv);
        integer i;
        integer num_list=llGetListLength(my_list);
        for (i=0; i<num_list; ++i)
        {
            llOwnerSay("my_list[" + (string)i + "]: " + llList2String(my_list,i));
        }
    }
}
</syntaxhighlight>
|helpers
|also_functions={{LSL DefineRow||[[llList2CSV]]|}}
{{LSL DefineRow||[[llDumpList2String]]|}}
{{LSL DefineRow||[[llParseString2List]]|}}
{{LSL DefineRow||[[llParseStringKeepNulls]]|}}
|also_events
|also_tests
|also_articles={{LSL DefineRow||[[Typecast]]|}}
|notes=To use separators other than commas (especially if you can't predict when a user might have sneaked a comma into data they supply the script), use [[llParseString2List]] instead, which allows you to specify separators other than commas. [[llParseString2List]] unfortunately does not support the special parsing required for handling rotations and vectors, nor does it consume leading and trailing whitespace.
|permission
|negative_index
|sort=CSV2List
|cat1=List
|cat2=String
|cat3=Data Conversion
|cat4=CSV
}}

