|func=llEdgeOfWorld
|sort=EdgeOfWorld
|func_id=205|func_sleep=0.0|func_energy=10.0
|return_type=integer|return_subtype=boolean
|p1_type=vector|p1_name=pos|p1_desc
|p2_type=vector|p2_subtype=direction|p2_name=dir|p2_desc=direction
