{{LSL_Function
|func_id=315|func_sleep=0.0|func_energy=10.0
|func=llListStatistics|return_type=float|p1_type=integer|p1_name=operation|p1_desc=a LIST_STAT_* flag
|p2_type=list|p2_name=src
|func_footnote=If a list entry type is not a float or an integer it is silently ignored. 
|func_desc
|return_text=that is the result of performing statistical aggregate function {{LSLP|operation}} on {{LSLP|src}}.
|spec
|caveats
|constants={{{!}} class="sortable" {{Prettytable|style=margin-top:0;}}
{{!}}-{{Hl2}}
!Constant
! title="Value" {{!}}
! class="unsortable" {{!}} Description
{{!}}-
