[[Category:Experience Tools]]
{{LSL_Function
|inject-2={{Issues/BUG-8895}}
{{LSL Function/KeyValue|k|value=value|d2_type=string|d2_name=value}}
{{LSL Function/Experience|true}}
|func=llReadKeyValue
|func_desc=Start an asynchronous transaction to read the value associated with the specified key ({{LSLPT|k}}) and the script's {{LSLGC|Experience}}.
|func_footnote=If the key does not exist the [[dataserver]] will return a failure along with the error [[XP_ERROR_KEY_NOT_FOUND]].
|return_type=key|return_subtype=handle
|return_text=that can be used to identify the corresponding [[dataserver]] event to determine if this command succeeded or failed and the results.
|p1_type=string|p1_name=k
|also_functions=
*[[llGetExperienceErrorMessage]]
*[[llCreateKeyValue]]
*[[llReadKeyValue]]
*[[llUpdateKeyValue]]
*[[llDeleteKeyValue]]
*[[llDataSizeKeyValue]]
*[[llKeyCountKeyValue]]
*[[llKeysKeyValue]]
|examples=<syntaxhighlight lang="lsl2">key trans;
default
{
    state_entry()
    {
        trans = llReadKeyValue("FOO");
    }
    dataserver(key t, string value)
    {
        if (t == trans)
        {
            // our llReadKeyValue transaction is done
            if (llGetSubString(value, 0, 0) == "1")
            {
                // the key-value pair was successfully read
                llSay(0, "New key-value pair value: " + llGetSubString(value, 2, -1));
            }
            else
            {
                // the key-value pair failed to read
                integer error =  (integer)llGetSubString(value, 2, -1);
                llSay(0, "Key-value failed to read: " + llGetExperienceErrorMessage(error));
            }
        } 
    }
}</syntaxhighlight>
|haiku={{Haiku|Async read starts now,|Key sought in Experience,|Hope it's not missing!|author=ChatGPT}}
|cat1=Experience
|cat2=Experience/Data
|cat3=Dataserver
}}

{{LSL_Function
|inject-2={{LSL_Function/chat|channel|msg|np=*}}
|func_id=331
|func_sleep=0.0
|func_energy=10.0
|func=llRegionSay
|p1_type=integer|p1_name=channel|p1_desc
|p2_type=string|p2_name=msg|p2_desc
|func_desc=Says the string {{LSLP|msg}} on channel number {{LSLP|channel}} that can be heard anywhere in the [[region]] by a script [[listen|listening]] on {{LSLP|channel}}.
|func_footnote=Regardless of where the prim is, the message will not travel over region borders.
|return_text
|spec
|constants
|caveats=*This function cannot transmit on {{#var:PUBLIC_CHANNEL}} channel 0, this is a design feature and not a bug.
*If {{LSLP|msg}} is longer than 1024 characters it is truncated to 1024 characters. (Note that in Mono, each character occupies 2 memory bytes).
*A prim can '''not''' hear itself, this to prevent problems with recursion. It can however hear other prims within the same object. Use [[llMessageLinked]] instead for intra-prim messaging.
|examples=<source lang="lsl2">default
{
    state_entry()
    {
        llRegionSay(25,"This is an incredibly useless program." );
    }
}</source>
To avoid making your object spam its neighborhood, use [[llOwnerSay]] or [[llInstantMessage]].
|helpers
|also_events=
{{LSL DefineRow||[[listen]]|}}
|also_functions=
{{LSL DefineRow||[[llListen]]|}}
{{LSL DefineRow||[[llRegionSayTo]]|Sends chat directly to specified target within region}}
{{LSL DefineRow||[[llOwnerSay]]|Sends chat to the owner only}}
{{LSL DefineRow||[[llWhisper]]|Sends chat limited to 10 meters}}
{{LSL DefineRow||[[llSay]]|Sends chat limited to 20 meters}}
{{LSL DefineRow||[[llShout]]|Sends chat limited to 100 meters}}
{{LSL DefineRow||[[llInstantMessage]]|}}
{{LSL DefineRow||[[llDialog]]|}}
{{LSL DefineRow||[[llTextBox]]|}}
|also_tests
|also_articles
|notes=If one object 'says' something to another object (e.g., a button that, when touched,
turns on a lamp), consider a very negative channel, e.g.,
<source lang="lsl2">    llRegionSay(-5243212,"turn on");</source>
Using negative channels for script communications remains a common practice because, prior to September 2016, the standard SL client was unable to chat on negative channels. The only way to do so prior to [[llTextBox]] was to use [[llDialog]] which was limited to 24 bytes. However, since 2016, viewers have been able to chat on negative channels, with messages capped to 254 bytes.

If DEBUG_CHANNEL is used as {{LSLP|channel}}, the script will say {{LSLP|msg}} to the Script Warning/Error window. 

If you wish two objects owned by the same person to communicate within a SIM, one idea is to make both scripts compute the channel based on the owner UUID. e.g. :-
<source lang="lsl2">
    gChannel = 0x80000000 | (integer) ( "0x" + (string) llGetOwner() );
</source>

* As of 1.18.3, using llRegionSay on the {{#var:DEBUG_CHANNEL}} will wrap around and display on channel 0, with a range of 100m.
|history=
*Introduced with SL 1.16.0
* Date of Release [[ Release_Notes/Second_Life_Release/1.16 | 23-05-2007 ]]
|cat1=Communications
|cat2=Chat
|cat3
|cat4
}}

{{LSL_Function
|inject-2={{Issues/SCR-66}}
{{LSL_Function/uuid|target|sim=*|group=}}
|func_id=363
|func_sleep=0.0
|func_energy=10.0
|func=llRegionSayTo
|sort=RegionSayTo
|p1_type=key|p1_name=target
|p2_type=integer|p2_name=channel
|p3_type=string|p3_name=msg
|func_desc=Says<ref name="send">In this context, ''saying'' or ''speaking'' means that a message is being ''sent'' to the recipient (object or avatar); it's not about audio/voice chat!</ref> the text supplied in string {{LSLP|msg}} on channel supplied in [[integer]] {{LSLP|channel}} to the [[object]] or [[avatar]] specified by {{LSLP|target}}
|return_text
|spec
|caveats=
*Text is spoken<ref name="send" /> directly to the [[object]] or [[avatar]] within the same [[region]] as the [[script]].
*Script in tasks other than {{LSLP|target}} can neither listen for<ref>In this context, this means waiting to ''receive'' a message.</ref>, nor receive these text messages, with an exception for attachments as described below.
*{{LSLP|msg}} can be a maximum of 1024 bytes. This can convey 1024 ASCII characters, or 256-512 multibyte UTF-8 characters such as <code>á</code> (2 bytes), <code>ℋ</code> (3 bytes) or <code>🧡</code> (4 bytes).
*A [[prim]] cannot hear itself, to prevent problems with recursion. Use [[llMessageLinked]] instead for intra-prim messaging.
*Sending text on {{LSLP|DEBUG_CHANNEL}} is not supported.
*Text sent to an avatar's [[UUID|ID]] on channel [[PUBLIC_CHANNEL|zero]] will be sent to the receiver's viewer.
*Text sent to an avatar's ID on non-zero channels can be heard<ref>I.e., ''received''</ref> by any attachment on the avatar.
*A quick series of messages sent by [[llRegionSayTo]] cannot be relied on to arrive at their destination in the same order as sent.
*There is a per-destination throttle of 200 messages sent over 10 seconds on channel [[PUBLIC_CHANNEL|zero]].   Thereafter, there is also a per-sending-object throttle of 100 messages on channel zero over 300 seconds (5 minutes).  This throttle is relevant only after the first throttle is activated.  Messages sent on channels other than zero do not trigger the throttle but, once it is triggered, the block applies to ''all'' channels. The block is region-wide and applies to all objects with the same [[:Category:LSL_Owner|owner]]. The block apparently lasts until the region is restarted.
|examples=
<syntaxhighlight lang="lsl2">
default
{
    touch_start(integer num_detected)
    {
        key id = llDetectedKey(0);

        // send a message to the chat window of the avatar touching
        llRegionSayTo(id, 0, "You touched this!");

        // send a message to the attachments of the avatar touching
        // example channel: -12345
        llRegionSayTo(id, -12345, "Hello there attachments!");
    }
}
</syntaxhighlight>
|helpers
|also_events=
{{!}}-
{{!}}{{!}}{{!}} style="width:9em;" {{!}}
{{LSL DefineRow||[[listen]]|Receives chat}}
|also_functions=
{{!}}-
{{!}}{{!}}{{!}} style="width:9em;" {{!}}
{{LSL DefineRow||[[llListen]]|Ask for [[listen]] events}}
{{LSL DefineRow||[[llInstantMessage]]|Sends chat to a specific avatar, inside or outside the current region.}}
{{LSL DefineRow||[[llOwnerSay]]|Sends chat to the owner only to avoid spamming the [[PUBLIC_CHANNEL]]}}
{{LSL DefineRow||[[llRegionSay]]|Sends chat region wide}}
{{LSL DefineRow||[[llSay]]|Sends chat limited to 20 meters}}
{{LSL DefineRow||[[llShout]]|Sends chat limited to 100 meters}}
{{LSL DefineRow||[[llWhisper]]|Sends chat limited to 10 meters}}
|also_tests
|also_articles={{LSL DefineRow||[[Hello Avatar]]}}
|notes=
* If one object 'says'<ref name="send" /> something to another object (''e.g.'', a button that, when touched, turns on a lamp), consider using a very negative {{LSLP|channel}}, ''e.g.'',
:<syntaxhighlight lang="lsl2">llRegionSayTo("55499a64-45c3-4b81-8880-8ffb5a7c251b", -5243212, "turn on");</syntaxhighlight>
:Using negative channels for script communications remains a common practice because, prior to September 2016, the standard Second Life Viewer was unable to chat directly on those channels (<kbd>/-xxxx message</kbd> wouldn't chat {{mono|message}} on {{LSLPT|channel}} {{mono|-xxxx}}). 
* Messages sent on channel zero via [[llRegionSayTo]]() are blocked after 200 messages on to the same destination in a 10 second period.  After this throttle is activated, there is a further throttle, on objects belonging to the owner of the object that triggered the first throttle, of 100 messages per object over 5 minutes (see {{Jira|BUG-5457}}). The block is region-wide and applies to all objects belonging to the owner, so if a script triggers the throttle, all objects in the same region belonging to the same owner will also be blocked. Messages sent on channels other than zero do not trigger the throttles.  The throttles apparently reset only when the region is restarted. 

Therefore, [[llRegionSayTo]]() is unsuitable for (say) verbose script debugging, and even moderate use can break users' content completely unrelated to the script for an indeterminate (and potentially very long) period of time.   Consider using [[llOwnerSay]]() for debugging instead or, if this is not appropriate, try {{mono|llRegionSayTo(avatar, non-zero-channel, message)}} and have an attachment relay the message using [[llOwnerSay]](). 
|cat1
|cat2
|cat3
|cat4
|history = Date of Release  [[ Release_Notes/Second_Life_Server/11#11.04.26.227686 | 26/04/2011 ]]
}}

[[Category:LSL_Chat]]

{{LSL_Function
|func_id=347|func_sleep=0.0|func_energy=10.0
|func=llReleaseURL|return_type
|p1_type=string|p1_name=url|p1_desc=URL to release
|func_footnote
|func_desc=Releases the specified URL, it will no longer be usable.
|return_text
|spec
|caveats=*URLs are automatically released and invalidated in certain situations. In the following situations, there is no need to call llReleaseURL. But you will have to request a new one afterwards
**When the region is restarted or goes offline
**When the script holding the URLs is reset, or recompiled
**When the object containing the script is deleted, or taken to inventory
|constants
|examples=
{{LSL Tip|Never ever forget to release a URL again which you have requested! URLs are region resources just like prims. If you take them all you can get into big trouble with the sim owner and/or estate managers.}}
<source lang="lsl2">
string url;
key urlRequestId;
key selfCheckRequestId;

request_url()
{
    llReleaseURL(url);
    url = "";
    llSetTimerEvent(0.0);
    urlRequestId = llRequestURL();
}

throw_exception(string inputString)
{
    llInstantMessage(llGetOwner(), inputString);

    // yeah, bad way to handle exceptions by restarting.
    // However this is just a demo script...

    llResetScript();
}

default
{
    on_rez(integer start_param)
    {
        llResetScript();
    }

    changed(integer change)
    {
        if (change & CHANGED_OWNER | CHANGED_REGION | CHANGED_REGION_START)
            llResetScript();
    }

    state_entry()
    {
        request_url();
    }

    http_request(key id, string method, string body)
    {
        integer responseStatus = 400;
        string responseBody = "Unsupported method";

        if (method == URL_REQUEST_DENIED)
            throw_exception("The following error occurred while attempting to get a free URL for this device:\n \n" + body);
        else if (method == URL_REQUEST_GRANTED)
        {
            url = body;
            llLoadURL(llGetOwner(), "Click to visit my URL!", url);

            // check every 5 mins for dropped URL
            llSetTimerEvent(300.0);
        }
        else if (method == "GET")
        {
            responseStatus = 200;
            responseBody = "Hello world!";
        }
        // else if (method == "POST") ...;
        // else if (method == "PUT") ...;
        // else if (method == "DELETE") { responseStatus = 403; responseBody = "forbidden"; }

        llHTTPResponse(id, responseStatus, responseBody);
    }

    http_response(key id, integer status, list metaData, string body)
    {
        if (id == selfCheckRequestId)
        {
            // If you're not usually doing this,
            // now is a good time to get used to doing it!
            selfCheckRequestId = NULL_KEY;

            if (status != 200)
                request_url();
        }
        else if (id == NULL_KEY)
            throw_exception("Too many HTTP requests too fast!");
    }

    timer()
    {
        selfCheckRequestId = llHTTPRequest(url,
                                [HTTP_METHOD, "GET",
                                    HTTP_VERBOSE_THROTTLE, FALSE,
                                    HTTP_BODY_MAXLENGTH, 16384],
                                "");
    }
}
</source>
