[[Category:Experience Tools]]
{{LSL_Function
|inject-2={{LSL Function/Experience|true}}
|func=llRequestExperiencePermissions
|func_desc=Asks the agent for permission to participate in the script's {{LSLGC|Experience}}.
|func_footnote=This request is similar to [[llRequestPermissions]] with all the following permissions: [[PERMISSION_TAKE_CONTROLS]], [[PERMISSION_TRIGGER_ANIMATION]], [[PERMISSION_ATTACH]], [[PERMISSION_TRACK_CAMERA]], [[PERMISSION_CONTROL_CAMERA]] and [[PERMISSION_TELEPORT]].  However, unlike [[llRequestPermissions]], the decision to allow or block the request is persistent and applies to all scripts using the experience grid-wide.  

Subsequent calls to llRequestExperiencePermissions from scripts in the experience will receive the same response automatically with no user interaction.  

Either [[experience_permissions]] or [[experience_permissions_denied]] will be generated in response to this call. If no response is given by the [[agent]], the request will time out after at least 5 minutes. Multiple requests by the same [[script]] can be made during this time out though the script can only have permission for one agent at a time.   

Agents in [[god mode]] will always see the permission dialog even if the experience has been previously approved.  

Outstanding permission requests will be lost if the script is de-[[Rez|rezzed]], moved to another [[region]], or reset.

|p1_type=key|p1_name=agent|p1_desc=[[Key]] of the agent to request permissions from
|p2_type=string|p2_name=name|p2_desc=Deprecated, no longer used
|also_events=
*[[experience_permissions]]
*[[experience_permissions_denied]]
|examples=

This is a shell for a [[HUD]] Dispenser.  It detects an [[avatar]] by the [[collision]] event, then rezzes an object that will request experience permissions and attach to the avatar:
<syntaxhighlight lang="lsl2">
default
{
    state_entry()
    {
        llVolumeDetect(TRUE);
    }

    collision_start(integer NumberOfCollisions)
    {
        integer i = 0;
        for(; i < NumberOfCollisions; i++)
        {
            integer channel = llRound(llFrand(-1000));
            key give_to = llDetectedKey(i);
            llSay(0, "Rezzing HUD for " + (string)give_to + " using channel " + (string)channel);
            llRezObject(llGetInventoryName(INVENTORY_OBJECT, 0), llGetPos(), ZERO_VECTOR, ZERO_ROTATION, channel);
            llRegionSay(channel, "ATTACH|" + (string)give_to);
        }
    }
}
</syntaxhighlight>

This script is for the object that is rezzed.  It requests experience permissions and then attaches itself to the avatar.   It must check for various failures such as denied permissions and failure to attach, and deletes itself when there is an error.
<syntaxhighlight lang="lsl2">
// Example script for LSL Experience Tools attachment

// This script runs on an object that is rezzed in-world which gets
// an Experience permissions and then attaches to an AV.

integer listener;
integer msg_channel;

integer log_spam_channel = 0;       // Change this or remove llSay() commands

default
{
    on_rez(integer start_parameter)
    {   // Start listening for a message from rezzer
        msg_channel = start_parameter;
        llSay(log_spam_channel, "Test HUD has been rezzed");
        listener = llListen(start_parameter, "", NULL_KEY, "");
    }

    listen(integer channel, string name, key id, string text)
    {   // Listen for the message from the rezzer with the target agent key
        if (channel == msg_channel)
        {   // Ask for the experience permission
            list msg = llParseString2List(text, ["|"], []);
            llSay(log_spam_channel, "Trying experience permissions request to " + llList2String(msg, 1));
            llRequestExperiencePermissions((key)llList2String(msg, 1), "");
            llListenRemove(listener);
            llSetTimerEvent(60.0);
        }
    }

    experience_permissions(key target_id)
    {   // Permissions granted, so attach to the AV
        llSay(log_spam_channel, "Trying llAttachToAvatarTemp()");
        llAttachToAvatarTemp(ATTACH_HUD_CENTER_1);
        llSay(log_spam_channel, "After llAttachToAvatarTemp() with llGetAttached() returning " + (string)llGetAttached());
        llSetTimerEvent(0.0);
        if (llGetAttached() == 0)
        {   // Attaching failed
            llDie();
        }
    }

    experience_permissions_denied( key agent_id, integer reason )
    {   // Permissions denied, so go away
        llSay(log_spam_channel, "Denied experience permissions for " + (string)agent_id + " due to reason #" + (string) reason);
        llDie();
    }

    attach( key id )
    {   // Attached or detached from the avatar
        if (id)
        {
            llSetTimerEvent(0.0);
            llSay(log_spam_channel, "Now attached with a key " + (string)id + " and llGetAttached() returning " + (string)llGetAttached());
            // From this point, the object can start doing whatever it needs to do.
            state running;
        }
        else
        {
            llSay(log_spam_channel, "No longer attached");
            llDie();
        }
    }

    timer()
    {   // Use a timer to catch no permissions response
        llSay(log_spam_channel, "Permissions timer expired");
        llDie();
    }
}

// This state starts when permissions are granted, and the object is properly attached
state running
{
    state_entry()
    {
        llSay(log_spam_channel, "off and running!");
    }

    attach(key id)
    {
        if (id == NULL_KEY)
        {   // if the object ever un-attaches, make sure it deletes itself
            llSay(log_spam_channel, "No longer attached");
            llDie();
        }
    }
}
</syntaxhighlight>
|cat1=Experience
|cat3=Permissions/Experience
}}

{{LSL_Function
|inject-2={{LSL_Function/inventory|name|uuid=false}}
|func_id=156|func_sleep=1.0|func_energy=10.0
|func=llRequestInventoryData
|return_type=key
|return_subtype=handle
|p1_type=string|p1_name=name|p1_desc
|func_footnote
|func_desc=Requests data about the item {{LSLP|name}} in the prim's inventory. When data is available the [[dataserver]] event will be raised.
|Return_text=that is used to identify the [[dataserver]] event when it is raised.
|spec
|caveats=
* This function only returns data for landmark items in inventory.  Other item types are not supported.
* The vector returned from landmarks is the distance in meters of the landmark's location relative to <0,0,0> in the region in which the script is running.
** For a landmark pointing to a location in the current region, that's the same as a region coordinate; however, when used with a landmark pointing to a different region the vector's x and y values can be quite large (and/or negative).
** The vector is suitable for use in calculating a global coordinate (as above) or a landmark's distance from the object containing the script in the current region or across the entire Second Life grid.
|constants=
{{{!}} {{Prettytable}}
{{!}}-{{Hl2}}
! colspan="2"{{!}} {{LSLPT|name}}'s Inventory Type 
!{{!}} [[dataserver]]
!{{!}} Description
{{!}}-
{{LSL Constants/llRequestInventoryData}}
{{!}}}
|examples=
<syntaxhighlight lang="lsl2">//-- Open map for owner to 1st landmark in object inventory on touch
//-- *MUST* be in an attached object (llMapDestination Requirement for non-touch use)
key vgKeyOwner;

default
{
  touch_start( integer vIntNull )
  {
    if (llDetectedKey( 0 ) == vgKeyOwner)
    {
      integer vIntLMcount = llGetInventoryNumber( INVENTORY_LANDMARK );
       //-- make sure we have a landmark in invetory
      if (vIntLMcount)
      {
        llRequestInventoryData( llGetInventoryName( INVENTORY_LANDMARK, 0 ) );
      }
    }
  }

  dataserver( key vKeyNull, string vStrData )
  {
     //-- because we don't know who touched us in this event, this
     //-- only works for the owner when called from the dataserver
    llMapDestination( llGetRegionName(), (vector)vStrData, ZERO_VECTOR );
  }

  on_rez( integer vIntNull )
  {
    llResetScript();
  }

  state_entry()
  {
    vgKeyOwner = llGetOwner();
  }
}</syntaxhighlight>
<syntaxhighlight lang="lsl2">//An easily-configurable teleporter that sets its destination by getting it from a landmark in the prim's inventory
//Note: this teleporter is subject to the 300m distance limit for llSitTarget
//by Ilse Mannonen

//on state entry, request inventory data and set text for first landmark found in inventory.  
//If none, complain
//on getting data, set sit target
//on change in inventory, reset script
//on sit, TP the person and unsit

//Thanks to Pol Tabla, who wrote the simple sit-teleport script I have adapted here

key requestid;

default
{
    state_entry()
    {
        //complain if there are no landmarks
        if (llGetInventoryNumber(INVENTORY_LANDMARK) == 0)
        {
            llSay(0, "There are no landmarks in me.  You need to put a landmark in me for me to work.");
        }
        else
        {
            //set floating text according to the LM name
            llSetText("Teleport to " + llGetInventoryName(INVENTORY_LANDMARK, 0), <1.0, 1.0, 1.0>, 1.0);
            //request the LM data
            requestid = llRequestInventoryData(llGetInventoryName(INVENTORY_LANDMARK, 0));
        }
    }

    dataserver(key id, string data)
    {
        if (id == requestid)
        {
            //data will be in vector format
            rotation rot = ZERO_ROTATION / llGetRot();
            vector dest = (vector)data;
            vector offset = (dest - llGetPos()) * rot;
            llSitTarget(offset, rot);
        }
    }

    changed(integer change)
    {
        if (change & CHANGED_LINK) 
        { // and it was a link change
            llSleep(0.5); // llUnSit works better with this delay
            key user = llAvatarOnSitTarget();
            if (user) { // somebody is sitting on me
                llUnSit(user); // unsit him
            }
        }
        //when doing "ifs" on bitwise things, it's best to do them separate instead of using else..if,
        //in case you hit the one in a billion chance when the inventory and link changes are reported in the same event.
        if (change & CHANGED_INVENTORY)
        {
            //reset on inventory change, so people don't have to manually reset when they add a new LM
            llResetScript();
        }
    }

    on_rez(integer param)
    {
        llResetScript();
    }
}</syntaxhighlight>
