<lsl>

dead(){
    key a = NULL_KEY;
    key b = NULL_KEY;
    key c = NULL_KEY;
    key d = NULL_KEY;
}

default {
    state_entry() {
        llOwnerSay((string) llGetFreeMemory());
    }
}</lsl>
|
<lsl>key null_key = NULL_KEY;

dead(){
    key a = null_key;
    key b = null_key;
    key c = null_key;
    key d = null_key;
}

default {
    state_entry() {
        llOwnerSay((string) llGetFreeMemory());
    }
}</lsl>
