|text=Used with [[llSetPrimitiveParams]] & [[llSetLinkPrimitiveParams]].

{{LSL Generic/Caveats|caveats={{#var:caveats_set}}{{#vardefine:caveats_set}}|issues={{#var:issues_set}}|title=*|h=4}}

====Examples====
<syntaxhighlight lang="lsl2">llSetPrimitiveParams([ PRIM_RENDER_MATERIAL, ALL_SIDES, my_render_material ]);
llSetPrimitiveParams([ PRIM_RENDER_MATERIAL, ALL_SIDES, llGetInventoryName(INVENTORY_MATERIAL, 0) ]);
llSetPrimitiveParams([ PRIM_RENDER_MATERIAL, 0, my_render_material ]);</syntaxhighlight>

|toc=llSetPrimitiveParams
|i1_type=integer|i1_name=face
|i2_type=string|i2_name=render_material
}}
