{{LSL Constant |name=VEHICLE_LINEAR_MOTOR_OFFSET |type=integer |value=20 |desc=Used with [[llSetVehicleVectorParam]] to set the offset for where the linear motor is to be applied from the vehicle's [[llGetCenterOfMass|center of mass]].
If the vehicle does not set the VEHICLE_LINEAR_MOTOR_OFFSET, then it defaults to [[ZERO_VECTOR|<0.0, 0.0, 0.0>]]. |notes=This could be useful in vehicles where the source of thrust is important, such as a rocket or an air ship. Most vehicles do not need to change this value from the default.
In rockets using this offset gives that very distinctive spiraling out of control. |examples |functions={{LSL DefineRow||[[llSetVehicleVectorParam]]|}} |events |articles={{LSL DefineRow||[[Linden Vehicle Tutorial]]}} |cat1=Vehicle/Parameters |cat2 |cat3 |cat4 }}

{{LSL Constant
|name={{PAGENAMEE}}
|type=integer
|value=4
|examples
|desc=Uses linear deflection for lift, no hover, and banking to turn.

===Effects===
Setting the vehicle type to airplane enables the vehicle system and additionally has the same effect of executing the following:
<source lang="lsl2">
// very little friction along forward-back axis
llSetVehicleVectorParam( VEHICLE_LINEAR_FRICTION_TIMESCALE, <200, 10, 5> );
// uniform angular friction
llSetVehicleFloatParam( VEHICLE_ANGULAR_FRICTION_TIMESCALE, 20 );
// linear motor
llSetVehicleVectorParam( VEHICLE_LINEAR_MOTOR_DIRECTION, <0, 0, 0> );
llSetVehicleFloatParam( VEHICLE_LINEAR_MOTOR_TIMESCALE, 2 );
llSetVehicleFloatParam( VEHICLE_LINEAR_MOTOR_DECAY_TIMESCALE, 60 );
// agular motor
llSetVehicleVectorParam( VEHICLE_ANGULAR_MOTOR_DIRECTION, <0, 0, 0> );
llSetVehicleFloatParam( VEHICLE_ANGULAR_MOTOR_TIMESCALE, 4 );
llSetVehicleFloatParam( VEHICLE_ANGULAR_MOTOR_DECAY_TIMESCALE, 8 );
// no hover
llSetVehicleFloatParam( VEHICLE_HOVER_HEIGHT, 0 );
llSetVehicleFloatParam( VEHICLE_HOVER_EFFICIENCY, 0.5 );
llSetVehicleFloatParam( VEHICLE_HOVER_TIMESCALE, 1000 );
llSetVehicleFloatParam( VEHICLE_BUOYANCY, 0 );
// linear deflection
llSetVehicleFloatParam( VEHICLE_LINEAR_DEFLECTION_EFFICIENCY, 0.5 );
llSetVehicleFloatParam( VEHICLE_LINEAR_DEFLECTION_TIMESCALE, 0.5 );
// angular deflection
llSetVehicleFloatParam( VEHICLE_ANGULAR_DEFLECTION_EFFICIENCY, 1.0 );
llSetVehicleFloatParam( VEHICLE_ANGULAR_DEFLECTION_TIMESCALE, 2.0 );
// vertical attractor
llSetVehicleFloatParam( VEHICLE_VERTICAL_ATTRACTION_EFFICIENCY, 0.9 );
llSetVehicleFloatParam( VEHICLE_VERTICAL_ATTRACTION_TIMESCALE, 2 );
// banking
llSetVehicleFloatParam( VEHICLE_BANKING_EFFICIENCY, 1 );
llSetVehicleFloatParam( VEHICLE_BANKING_MIX, 0.7 );
llSetVehicleFloatParam( VEHICLE_BANKING_TIMESCALE, 2 );
// default rotation of local frame
llSetVehicleRotationParam( VEHICLE_REFERENCE_FRAME, <0, 0, 0, 1> );
// remove these flags
llRemoveVehicleFlags( VEHICLE_FLAG_NO_DEFLECTION_UP
    | VEHICLE_FLAG_HOVER_WATER_ONLY
    | VEHICLE_FLAG_HOVER_TERRAIN_ONLY
    | VEHICLE_FLAG_HOVER_GLOBAL_HEIGHT
    | VEHICLE_FLAG_HOVER_UP_ONLY
    | VEHICLE_FLAG_LIMIT_MOTOR_UP );
// set these flags
llSetVehicleFlags( VEHICLE_FLAG_LIMIT_ROLL_ONLY );
</source>
